<style>
.xd6-gallery-section,.xd6-faq{padding:88px 0}.xd6-gallery-section .xd6-container,.xd6-faq .xd6-container{width:min(1240px,calc(100% - 64px));margin-inline:auto}
.xd6-gallery-section{background:#f4f3f0;color:#18181c}.xd6-gallery-section__head{display:grid;grid-template-columns:1fr .75fr;gap:48px;align-items:end;margin-bottom:36px}
.xd6-gallery-section .xd6-eyebrow,.xd6-faq .xd6-eyebrow{font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;margin:0 0 14px;color:#c92b22}
.xd6-gallery-section .xd6-section-title,.xd6-faq .xd6-section-title{font-size:clamp(28px,3vw,42px);font-weight:750;line-height:1.2;margin:0;letter-spacing:-.02em}
.xd6-gallery-section .xd6-section-title{color:#18181c}.xd6-gallery-section__head>p{font-size:15px;line-height:1.8;color:#63636a;margin:0}
.xd6-gallery-section .xd6-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.xd6-gallery-section .xd6-gallery{background:transparent}
.xd6-gallery-section .xd6-gallery__card:nth-child(n){grid-column:auto;min-height:0}
.xd6-gallery__card{display:flex;flex-direction:column;min-width:0;overflow:hidden;background:#fff;border:1px solid #e3e2de;border-radius:10px;color:#18181c;text-decoration:none;box-shadow:0 6px 20px #18181c06;transition:transform .2s,box-shadow .2s}
.xd6-gallery__card img{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;filter:none;transition:transform .3s}
.xd6-gallery__card .xd6-gallery__caption{position:static;background:#fff;display:flex;align-items:start;justify-content:space-between;gap:20px;padding:22px}.xd6-gallery__caption strong{font-size:17px;line-height:1.5;font-weight:650;color:#18181c}.xd6-gallery__caption i{font-style:normal;color:#c92b22;font-size:22px;line-height:1.2}
.xd6-gallery__card:hover{transform:translateY(-4px);box-shadow:0 16px 30px #18181c12}.xd6-gallery__card:focus-visible{outline:3px solid #c92b22;outline-offset:4px}
.xd6-faq{background:#101012;color:#f7f5f2;border-top:1px solid #28282e}.xd6-faq__grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:56px;align-items:start}
.xd6-faq .xd6-eyebrow{color:#ff7a71}.xd6-faq .xd6-section-title{color:#f7f5f2}.xd6-faq__intro{margin:18px 0 30px;color:#b9b9c0;font-size:15px;line-height:1.8;max-width:580px}
.xd6-faq__items{display:grid;gap:12px}.xd6-faq__items details{background:#1b1b20;border:1px solid #333339;border-radius:8px;overflow:hidden}.xd6-faq__items details[open]{border-color:#75433e}
.xd6-faq__items summary{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 22px;min-height:68px;list-style:none;cursor:pointer;color:#f7f5f2}.xd6-faq__items summary::-webkit-details-marker{display:none}.xd6-faq__items summary strong{font-size:16px;font-weight:600;line-height:1.5;color:#f7f5f2}
.xd6-faq__items summary span{display:grid;place-items:center;flex:0 0 28px;height:28px;border-radius:50%;background:#ff3b301a;color:#ff7a71}.xd6-faq__items summary span:before{content:'+';font-size:22px}.xd6-faq__items details[open] summary span:before{content:'−'}
.xd6-faq__items summary:focus-visible{outline:2px solid #ff7a71;outline-offset:-4px}.xd6-faq__items p{margin:0;padding:0 22px 22px;color:#c3c3ca;font-size:14px;line-height:1.9}
.xd6-faq__media{overflow:hidden;border:1px solid #333339;border-radius:10px;margin-top:6px;background:#1b1b20}.xd6-faq__media img{display:block;width:100%;aspect-ratio:4/5;object-fit:cover}.xd6-faq__media a{display:flex;justify-content:space-between;gap:20px;padding:22px;color:#f7f5f2;font-size:15px;font-weight:600}.xd6-faq__media a span{color:#ff7a71}
@media(max-width:900px){.xd6-gallery-section .xd6-gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.xd6-gallery-section__head{grid-template-columns:1fr;gap:18px}.xd6-faq__grid{grid-template-columns:minmax(0,1fr);gap:32px}.xd6-faq__media img{aspect-ratio:16/9}}
@media(max-width:600px){.xd6-gallery-section,.xd6-faq{padding:56px 0}.xd6-gallery-section .xd6-container,.xd6-faq .xd6-container{width:calc(100% - 32px)}.xd6-gallery-section .xd6-gallery{grid-template-columns:minmax(0,1fr);gap:20px}.xd6-gallery__caption{padding:20px}.xd6-faq__items summary{padding:18px}.xd6-faq__items p{padding:0 18px 18px}}
@media(prefers-reduced-motion:reduce){.xd6-gallery__card,.xd6-gallery__card img{transition:none}.xd6-gallery__card:hover{transform:none}}
</style>
